(nextval('planocontadetalhe_c95_sequencial_seq'), 3, '2.3.0.0.0.00.00.00.00.00', 'PATRIMÔNIO LIQUIDO', 'Compreende o valor residual dos ativos depois de deduzidos todos os passivos.', 0, false, 0, 'N', FALSE),
(nextval('planocontadetalhe_c95_sequencial_seq'), 3, '2.3.1.0.0.00.00.00.00.00', 'PATRIMÔNIO SOCIAL E CAPITAL SOCIAL', 'Compreende o patrimônio social das autarquias, fundações e fundos e o capital social das demais entidades da administração indireta.', 0, false, 0, 'N', FALSE),
