(nextval('planocontadetalhe_c95_sequencial_seq'), 3, '4.9.9.9.1.11.00.00.00.00', 'RESTITUICAO PELO PAGAMENTO INDEVIDO', 'Registra o valor da restituição proveniente de pagamento indevido.', 0, true, 0, 'N', FALSE),
(nextval('planocontadetalhe_c95_sequencial_seq'), 3, '4.9.9.9.1.12.00.00.00.00', 'RESTITUICAO DE AUXILIOS', 'Registra a arrecadação de recursos provenientes da devolução de saldos de auxílios.', 0, true, 0, 'N', FALSE),
